use std::hint::black_box;

use crate::harness::{INNER_ITERATIONS, WARMUP};

pub struct Overhead {
    pub timer_ns: u64,
    pub loop_iter_ns: u64,
}

impl Overhead {
    pub fn per_call_ns(&self) -> u64 {
        self.timer_ns / INNER_ITERATIONS + self.loop_iter_ns
    }
}

pub fn calibrate(samples: u64) -> Overhead {
    let timer_ns = calibrate_timer(samples);
    let loop_iter_ns = calibrate_loop(samples, timer_ns);
    Overhead {
        timer_ns,
        loop_iter_ns,
    }
}

fn calibrate_timer(samples: u64) -> u64 {
    for _ in 0..WARMUP {
        let s = minstant::Instant::now();
        black_box(s.elapsed().as_nanos());
    }
    let mut min_ns = u64::MAX;
    for _ in 0..samples {
        let s = minstant::Instant::now();
        let e = s.elapsed().as_nanos() as u64;
        if e < min_ns {
            min_ns = e;
        }
    }
    min_ns
}

fn calibrate_loop(samples: u64, timer_ns: u64) -> u64 {
    for _ in 0..WARMUP {
        let s = minstant::Instant::now();
        for _ in 0..INNER_ITERATIONS {
            black_box(());
        }
        black_box(s.elapsed().as_nanos());
    }
    let mut min_ns = u64::MAX;
    for _ in 0..samples {
        let s = minstant::Instant::now();
        for _ in 0..INNER_ITERATIONS {
            black_box(());
        }
        let e = s.elapsed().as_nanos() as u64;
        if e < min_ns {
            min_ns = e;
        }
    }
    min_ns.saturating_sub(timer_ns) / INNER_ITERATIONS
}

