    let cli = Cli::parse();

    println!(
        "iiac-perf {} — timer overhead measurement\n",
        env!("CARGO_PKG_VERSION")
    );

    let overhead = overhead::calibrate(CALIBRATION_SAMPLES);
    println!(
        "calibration (min over {} samples):",
        harness::fmt_commas(CALIBRATION_SAMPLES)
    );
    println!("  timer_overhead    {:>4} ns  (per Instant::now+elapsed pair)", overhead.timer_ns);
    println!("  loop_iter_cost    {:>4} ns  (per empty loop iteration)", overhead.loop_iter_ns);
    println!("  per_call_overhead {:>4} ns  (subtracted from adjusted column)", overhead.per_call_ns());
    println!();

    benches::timer::run(cli.iterations, &overhead);
}

